@charset "UTF-8";
*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  padding: 0;
  background: #ffffff;
  color: #475569;
  overflow-x: hidden;
}

img {
  display: block;
  max-width: 100%;
  height: auto;
}

button,
input,
textarea,
select {
  font-family: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

a {
  text-decoration: none;
}

.container {
  width: min(100% - 48px, 1200px);
  margin-inline: auto;
}

.container-wide {
  width: min(100% - 48px, 1400px);
  margin-inline: auto;
}

.section {
  width: 100%;
  padding-block: 60px;
}

.section-sm {
  width: 100%;
  padding-block: 64px;
}

.section-lg {
  width: 100%;
  padding-block: 120px;
}

.section-header {
  margin-bottom: 26px;
}

.section-header__eyebrow {
  margin-bottom: 7px;
}

.section-header__title {
  margin-bottom: 24px;
}

.section-header__description {
  max-width: 580px;
}

.text-narrow {
  max-width: 430px;
}

.text-medium {
  max-width: 580px;
}

.text-wide {
  max-width: 680px;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 48px;
  padding: 12px 22px;
  border: 0;
  border-radius: 999px;
  font-family: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 14px;
  font-weight: 600;
  line-height: 1;
  cursor: pointer;
  transition: background-color 0.3s ease, color 0.3s ease, border-color 0.3s ease, transform 0.3s ease;
}

.btn:hover {
  transform: translateY(-2px);
}

.btn-primary {
  background: #08274b;
  color: #ffffff;
}

.btn-primary:hover {
  background: #03152e;
}

.btn-blue {
  background: #007aff;
  color: #ffffff;
}

.btn-blue:hover {
  background: #062b66;
}

.btn-outline {
  background: transparent;
  color: #08274b;
  border: 1px solid #08274b;
}

.btn-outline:hover {
  background: #08274b;
  color: #ffffff;
}

.card {
  border-radius: 20px;
  background: #ffffff;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

@media (max-width: 768px) {
  .container,
  .container-wide {
    width: min(100% - 32px, 1200px);
  }
  .section {
    padding-block: 64px;
  }
  .section-sm {
    padding-block: 48px;
  }
  .section-lg {
    padding-block: 80px;
  }
  .section-header {
    margin-bottom: 36px;
  }
}
body {
  font-family: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
  font-weight: 400;
  line-height: 1.5;
  color: #475569;
}

h1,
.heading-hero {
  font-family: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: clamp(42px, 5vw, 58px);
  line-height: 1.05;
  font-weight: 700;
  letter-spacing: -1.5px;
  color: #08274b;
  margin: 0;
}

h2,
.heading-section {
  font-family: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: clamp(34px, 4vw, 46px);
  line-height: 1.1;
  font-weight: 700;
  letter-spacing: -0.8px;
  color: #08274b;
  margin: 0;
}

h3,
.heading-card {
  font-family: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 22px;
  line-height: 1.25;
  font-weight: 700;
  letter-spacing: -0.2px;
  color: #08274b;
  margin: 0;
}

h4 {
  font-family: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 18px;
  line-height: 1.3;
  font-weight: 600;
  color: #08274b;
  margin: 0;
}

p,
.body-text {
  font-family: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
  line-height: 1.5;
  font-weight: 400;
  color: #475569;
  margin: 0;
}

.body-large {
  font-family: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 18px;
  line-height: 1.7;
  font-weight: 400;
  color: #64748b;
}

.eyebrow {
  display: inline-block;
  font-family: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 12px;
  line-height: 1;
  font-weight: 700;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  color: #007aff;
}

.eyebrow--light {
  color: #f59a18;
}

.text-small {
  font-family: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 14px;
  line-height: 1.5;
  font-weight: 400;
  color: #64748b;
}

strong,
.text-bold {
  font-weight: 700;
}

a {
  font-family: inherit;
  color: inherit;
}

@media (max-width: 768px) {
  h1,
  .heading-hero {
    font-size: clamp(36px, 10vw, 44px);
    letter-spacing: -1px;
  }
  h2,
  .heading-section {
    font-size: clamp(30px, 8vw, 36px);
    letter-spacing: -0.5px;
  }
  h3,
  .heading-card {
    font-size: 20px;
  }
  p,
  .body-text {
    font-size: 16px;
    line-height: 1.6;
  }
  .body-large {
    font-size: 17px;
  }
  .eyebrow {
    font-size: 11px;
    letter-spacing: 1.3px;
  }
}
.site-header {
  background: transparent;
}

.site-header.scrolled {
  background: rgba(11, 19, 43, 0.9);
  backdrop-filter: blur(18px);
  box-shadow: 0 15px 50px rgba(0, 0, 0, 0.1);
}

/* --- Component Specific Glass Tokens (Derived from System) --- */
/* --- Header Layout --- */
.site-header {
  position: absolute;
  top: 0;
  left: 0;
  z-index: 1000;
  width: 100%;
  font-family: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.88) 0%, rgba(255, 255, 255, 0.68) 60%, rgba(255, 255, 255, 0) 100%);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  transition: background 0.5s ease, backdrop-filter 0.5s ease, box-shadow 0.5s ease;
}
.site-header .navbar-container {
  width: min(88%, 1400px);
  min-height: 82px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}
.site-header {
  /* Logo */
}
.site-header .navbar-logo {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
}
.site-header .navbar-logo .logo-link {
  display: inline-flex;
  align-items: center;
  text-decoration: none;
  outline: none;
}
.site-header .navbar-logo .logo-link .logo-img {
  display: block;
  width: 225px;
  height: auto;
  max-width: 100%;
  object-fit: contain;
}
.site-header {
  /* Navigation Base */
}
.site-header .main-navigation {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 24px;
  margin-left: auto;
}
.site-header .nav-menu {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 24px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.site-header .nav-menu li {
  position: relative;
  margin: 0;
  padding: 0;
  list-style: none;
}
.site-header .nav-menu li::before, .site-header .nav-menu li::after {
  display: none;
}
.site-header .nav-menu {
  /* Top-Level Menu Items */
}
.site-header .nav-menu > li {
  position: relative;
}
.site-header .nav-menu > li > a {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 82px;
  padding: 0;
  color: #08274b;
  background: transparent;
  text-decoration: none;
  font-family: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
  font-weight: 700;
  line-height: 1.1;
  white-space: nowrap;
  outline: none;
  transition: color 0.2s ease;
  /* Active/Hover Indicator Bar */
}
.site-header .nav-menu > li > a::after {
  content: "";
  position: absolute;
  left: 0;
  bottom: 18px;
  width: 0;
  height: 2px;
  border-radius: 999px;
  background: #f59a18;
  transition: width 0.3s ease;
}
.site-header .nav-menu > li:hover > a, .site-header .nav-menu > li.current-menu-item > a, .site-header .nav-menu > li.current-menu-ancestor > a {
  color: #08274b;
}
.site-header .nav-menu > li:hover > a::after, .site-header .nav-menu > li.current-menu-item > a::after, .site-header .nav-menu > li.current-menu-ancestor > a::after {
  width: 100%;
}
.site-header .nav-menu > li {
  /* Dropdown Arrow Indicator */
}
.site-header .nav-menu > li.menu-item-has-children > a {
  padding-right: 15px;
}
.site-header .nav-menu > li.menu-item-has-children > a::before {
  content: "";
  display: block;
  position: absolute;
  top: 50%;
  right: 1px;
  width: 5px;
  height: 5px;
  border-right: 1px solid rgba(8, 39, 75, 0.65);
  border-bottom: 1px solid rgba(8, 39, 75, 0.65);
  transform: translateY(-70%) rotate(45deg);
  transition: transform 0.2s ease;
}
.site-header .nav-menu > li.menu-item-has-children:hover > a::before {
  transform: translateY(-35%) rotate(225deg);
}
.site-header .nav-menu > li {
  /* Level 1 Submenu */
}
.site-header .nav-menu > li > .sub-menu {
  position: absolute;
  top: calc(100% - 4px);
  left: 50%;
  z-index: 100;
  min-width: 225px;
  margin: 0;
  padding: 7px;
  list-style: none;
  background: rgba(3, 21, 46, 0.97);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 16px;
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.3);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transform: translate(-50%, 10px);
  transition: opacity 0.2s ease, visibility 0.2s ease, transform 0.2s ease;
}
.site-header .nav-menu > li > .sub-menu > li {
  position: relative;
  width: 100%;
}
.site-header .nav-menu > li > .sub-menu > li > a {
  position: relative;
  display: flex;
  align-items: center;
  width: 100%;
  min-height: 40px;
  padding: 8px 7px;
  border-radius: 8px;
  color: #64748b;
  background: transparent;
  text-decoration: none;
  font-size: 14px;
  font-weight: 400;
  white-space: nowrap;
  transition: color 0.2s ease, background 0.2s ease, padding-left 0.2s ease;
}
.site-header .nav-menu > li > .sub-menu > li > a::after {
  display: none;
}
.site-header .nav-menu > li > .sub-menu > li > a:hover {
  padding-left: 16px;
  color: #ffffff;
  background: rgba(255, 255, 255, 0.08);
}
.site-header .nav-menu > li > .sub-menu > li.current-menu-item > a {
  color: #ffffff;
  background: rgba(0, 122, 255, 0.15);
}
.site-header .nav-menu > li > .sub-menu > li.current-menu-item > a::before {
  content: "";
  width: 6px;
  height: 6px;
  flex: 0 0 6px;
  margin-right: 8px;
  border-radius: 50%;
  background: #10b981;
}
.site-header .nav-menu > li > .sub-menu > li {
  /* Level 2 Submenu */
}
.site-header .nav-menu > li > .sub-menu > li.menu-item-has-children > a {
  padding-right: 25px;
}
.site-header .nav-menu > li > .sub-menu > li.menu-item-has-children > a::after {
  content: "";
  display: block;
  position: absolute;
  right: 12px;
  top: 50%;
  width: 5px;
  height: 5px;
  border-right: 1px solid rgba(255, 255, 255, 0.6);
  border-bottom: 1px solid rgba(255, 255, 255, 0.6);
  transform: translateY(-50%) rotate(-45deg);
}
.site-header .nav-menu > li > .sub-menu > li.menu-item-has-children > .sub-menu {
  position: absolute;
  top: -7px;
  left: calc(100% + 8px);
  min-width: 210px;
  margin: 0;
  padding: 7px;
  background: rgba(3, 21, 46, 0.97);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 16px;
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.3);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transform: translateX(8px);
  transition: opacity 0.2s ease, visibility 0.2s ease, transform 0.2s ease;
}
.site-header .nav-menu > li > .sub-menu > li.menu-item-has-children:hover > .sub-menu {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
  transform: translateX(0);
}
.site-header .nav-menu > li:hover > .sub-menu {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
  transform: translate(-50%, 0);
}
.site-header {
  /* Language Switcher (GTranslate) */
}
.site-header .vv-language-switcher {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 38px;
  padding: 0 10px;
  border: 1px solid #e2e8f0;
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.78);
  color: #08274b;
  font-size: 12px;
  font-weight: 600;
  white-space: nowrap;
  transition: background 0.2s ease, border-color 0.2s ease;
}
.site-header .vv-language-switcher:hover {
  background: #ffffff;
  border-color: rgba(8, 39, 75, 0.25);
}
.site-header .vv-language-switcher .vv-language-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  line-height: 1;
}
.site-header .vv-language-switcher .gtranslate_wrapper,
.site-header .vv-language-switcher .gt_switcher_wrapper,
.site-header .vv-language-switcher .gt_float_wrapper {
  display: inline-flex;
  align-items: center;
  font-family: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 12px;
}
.site-header .vv-language-switcher select,
.site-header .vv-language-switcher .gt_selector {
  border: 0;
  background: transparent;
  color: #08274b;
  font-family: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  outline: none;
  padding-right: 2px;
}
.site-header .vv-language-switcher a.glink {
  color: #08274b;
  text-decoration: none;
  font-weight: 600;
  padding: 2px 4px;
  border-radius: 8px;
}
.site-header .vv-language-switcher a.glink:hover {
  background: rgba(8, 39, 75, 0.06);
}
.site-header {
  /* Primary Call to Action Button */
}
.site-header .header-learning-btn {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 40px;
  padding: 0 16px;
  border: 1px solid #f59a18;
  border-radius: 8px;
  background: #f59a18;
  color: #ffffff;
  text-decoration: none;
  font-size: 14px;
  font-weight: 600;
  white-space: nowrap;
  box-shadow: 0 7px 20px rgba(245, 154, 24, 0.25);
  transition: background 0.2s ease, transform 0.2s ease, box-shadow 0.2s ease;
}
.site-header .header-learning-btn:hover {
  background: rgb(91.5279472785%, 55.4714831991%, 3.9622487999%);
  transform: translateY(-1px);
  box-shadow: 0 9px 25px rgba(245, 154, 24, 0.35);
}
.site-header .header-learning-btn:hover .learning-arrow {
  transform: translate(2px, -2px);
}
.site-header .header-learning-btn .learning-arrow {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.2);
  color: #ffffff;
  font-size: 12px;
  transition: transform 0.2s ease;
}
.site-header {
  /* Mobile Hamburger Toggle */
}
.site-header .menu-toggle {
  display: none;
  flex: 0 0 auto;
  width: 42px;
  height: 42px;
  padding: 0;
  border: 1px solid #e2e8f0;
  border-radius: 8px;
  background: #ffffff;
  color: #08274b;
  cursor: pointer;
  align-items: center;
  justify-content: center;
}
.site-header .menu-toggle .hamburger-bar {
  position: relative;
  display: block;
  width: 20px;
  height: 2px;
  border-radius: 999px;
  background: #08274b;
  transition: background 0.3s ease;
}
.site-header .menu-toggle .hamburger-bar::before, .site-header .menu-toggle .hamburger-bar::after {
  content: "";
  position: absolute;
  left: 0;
  width: 20px;
  height: 2px;
  border-radius: 999px;
  background: #08274b;
  transition: transform 0.3s ease, top 0.3s ease;
}
.site-header .menu-toggle .hamburger-bar::before {
  top: -6px;
}
.site-header .menu-toggle .hamburger-bar::after {
  top: 6px;
}
.site-header .menu-toggle[aria-expanded=true] .hamburger-bar {
  background: transparent;
}
.site-header .menu-toggle[aria-expanded=true] .hamburger-bar::before {
  top: 0;
  transform: rotate(45deg);
}
.site-header .menu-toggle[aria-expanded=true] .hamburger-bar::after {
  top: 0;
  transform: rotate(-45deg);
}
.site-header {
  /* Sticky State */
}
.site-header.is-sticky {
  position: fixed;
  background: rgba(255, 255, 255, 0.94);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  box-shadow: 0 8px 30px rgba(8, 39, 75, 0.12);
}
.site-header.is-sticky .navbar-container {
  min-height: 70px;
}
.site-header.is-sticky .nav-menu > li > a {
  min-height: 70px;
}
.site-header.is-sticky .nav-menu > li > a::after {
  bottom: 14px;
}
.site-header.is-sticky .logo-img {
  width: 200px;
}

