  }
  .site-header.is-sticky .navbar-logo .logo-link .logo-img {
    width: 235px;
  }
}
@media (min-width: 1600px) and (max-width: 1919px) {
  .site-header .navbar-container {
    width: calc(100% - 80px);
    max-width: none;
    min-height: 92px;
