    font-size: 15px;
    min-height: 44px;
  }
  .site-header.is-sticky .navbar-container, .site-header.is-sticky .nav-menu > li > a {
    min-height: 78px;
  }
  .site-header.is-sticky .navbar-logo .logo-link .logo-img {
    width: 210px;
  }
