  animation: vvHstrideA 0.35s infinite alternate ease-in-out;
  transform-origin: 30px 21px;
}

@keyframes vvHpulse {
  0% {
    transform: scale(0.9);
    opacity: 0.85;
  }
  100% {
    transform: scale(1.45);
    opacity: 0;
  }
}
@keyframes vvHstrideA {
  from {
    transform: rotate(-18deg);
  }
  to {
    transform: rotate(18deg);
  }
}
@keyframes vvHstrideB {
  from {
    transform: rotate(18deg);
