/* =========================================================
   VIMA VIDYA
   DYNAMIC ASSESSMENT FLIP CARDS
========================================================= */
.vv-assessment-section {
  --navy: #08274b;
  --blue: #007aff;
  --cream: #fdfbf7;
  --gray: #64748b;
  --radius: 20px;
  --container: 1400px;
  --transition: 0.5s ease;
}

/* =========================================================
   ASSESSMENT SECTION
========================================================= */
.vv-assessment-section {
  background: var(--cream);
  padding: 64px 24px;
  font-family: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  /* =====================================================
      SECTION HEADER
  ===================================================== */
}
.vv-assessment-section .vv-assessment-header {
  max-width: 680px;
  margin: 0 auto 52px;
  text-align: center;
}
.vv-assessment-section .vv-assessment-header h2 {
  margin: 0 0 7px;
  color: var(--navy);
  font-size: 36px;
  line-height: 1.2;
  font-weight: 700;
  letter-spacing: -0.02em;
}
.vv-assessment-section .vv-assessment-header p {
  margin: 0;
  color: var(--blue);
  font-size: 16px;
  line-height: 1.5;
}
.vv-assessment-section {
  /* =====================================================
      GRID
  ===================================================== */
}
.vv-assessment-section .vv-assessment-grid {
  width: 100%;
  max-width: var(--container);
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 32px;
}
.vv-assessment-section {
  /* =====================================================
      CARD CONTAINER
  ===================================================== */
}
.vv-assessment-section .vv-assessment-card {
  position: relative;
  width: 100%;
  height: 540px;
  perspective: 1200px;
}
.vv-assessment-section {
  /* =====================================================
      HIDDEN CHECKBOX
  ===================================================== */
}
.vv-assessment-section .vv-flip-toggle {
  position: absolute;
  width: 1px;
  height: 1px;
  opacity: 0;
  pointer-events: none;
}
.vv-assessment-section {
  /* =====================================================
      FLIP CARD
  ===================================================== */
}
.vv-assessment-section .vv-flip-card {
  position: relative;
  display: block;
  width: 100%;
  height: 100%;
  cursor: pointer;
  transform-style: preserve-3d;
  transition: transform 0.65s cubic-bezier(0.4, 0, 0.2, 1);
}
.vv-assessment-section .vv-flip-toggle:checked + .vv-flip-card {
  transform: rotateY(180deg);
}
.vv-assessment-section {
  /* =====================================================
      CARD FACES
  ===================================================== */
}
.vv-assessment-section .vv-card-face {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  box-sizing: border-box;
  border-radius: var(--radius);
  overflow: hidden;
  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  box-shadow: 0 20px 45px color-mix(in srgb, var(--navy) 20%, transparent);
}
.vv-assessment-section {
  /* =====================================================
      FRONT
      SAME GRADIENT FOR ALL CARDS
  ===================================================== */
}
.vv-assessment-section .vv-card-front {
  padding: 32px;
  background: linear-gradient(135deg, var(--navy) 0%, var(--blue) 100%);
  color: var(--cream);
}
.vv-assessment-section {
  /* =====================================================
      FRONT CONTENT
  ===================================================== */
}
.vv-assessment-section .vv-front-content {
  width: 100%;
}
.vv-assessment-section {
  /* =====================================================
      CARD NUMBER
  ===================================================== */
}
.vv-assessment-section .vv-card-number {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 48px;
  height: 48px;
  margin-bottom: 20px;
  border-radius: 8px;
  background: var(--cream);
  color: var(--navy);
  font-size: 18px;
  font-weight: 800;
  letter-spacing: 0.02em;
}
.vv-assessment-section {
  /* =====================================================
      TITLE
  ===================================================== */
}
.vv-assessment-section .vv-card-title {
  margin: 0;
  color: var(--cream);
  font-size: 27px;
  line-height: 1.2;
  font-weight: 750;
  letter-spacing: -0.025em;
}
.vv-assessment-section {
  /* =====================================================
      DIVIDER
  ===================================================== */
}
.vv-assessment-section .vv-card-divider {
  width: 100%;
  height: 1px;
  margin: 18px 0;
  background: color-mix(in srgb, var(--cream) 22%, transparent);
}
.vv-assessment-section {
  /* =====================================================
      QUESTION
  ===================================================== */
}
.vv-assessment-section .vv-question {
  margin: 0;
  color: var(--cream);
  font-size: 15.5px;
  line-height: 1.5;
  opacity: 0.88;
}
.vv-assessment-section {
  /* =====================================================
          OPTIONS
      ===================================================== */
}
.vv-assessment-section .vv-options {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-top: 22px;
}
.vv-assessment-section .vv-option {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 7px 14px;
  border: 1px solid color-mix(in srgb, var(--cream) 12%, transparent);
  border-radius: 999px;
  /* Replaced linear-gradient with a solid semi-transparent background */
  background: color-mix(in srgb, var(--cream) 10%, transparent);
  color: var(--cream);
  transition: transform 0.3s ease, filter 0.3s ease, background-color 0.3s ease;
}
.vv-assessment-section .vv-option:hover {
  transform: translateY(-1px);
  /* Enhanced hover state for solid background */
  background: color-mix(in srgb, var(--cream) 18%, transparent);
}
.vv-assessment-section {
  /* =====================================================
      OPTION KEY
  ===================================================== */
}
.vv-assessment-section .vv-option-key {
  flex: 0 0 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--cream);
  color: var(--navy);
  font-size: 13px;
  font-weight: 800;
}
.vv-assessment-section {
  /* =====================================================
       OPTION TEXT
   ===================================================== */
}
.vv-assessment-section .vv-option-text {
  padding-top: 3px;
  /* Updated from $color-orange to white */
  color: #ffffff;
  font-size: 14px;
  line-height: 1.45;
  font-weight: 800;
}
.vv-assessment-section {
  /* =====================================================
      CARD ACTION
  ===================================================== */
}
.vv-assessment-section .vv-card-action {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding-top: 18px;
  color: var(--cream);
  font-size: 13px;
  font-weight: 650;
  opacity: 0.72;
}
.vv-assessment-section .vv-flip-icon {
  font-size: 18px;
}
.vv-assessment-section {
  /* =====================================================
      BACK
  ===================================================== */
}
.vv-assessment-section .vv-card-back {
  transform: rotateY(180deg);
  justify-content: center;
  padding: 30px;
  background: var(--cream);
  color: var(--navy);
  border: 1px solid color-mix(in srgb, var(--navy) 10%, transparent);
}
.vv-assessment-section {
  /* =====================================================
      BACK CONTENT
  ===================================================== */
}
.vv-assessment-section .vv-back-content {
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
}
.vv-assessment-section {
  /* =====================================================
      RECOMMENDED LABEL
  ===================================================== */
}
.vv-assessment-section .vv-answer-label {
  margin-top: 4px;
  color: var(--gray);
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.13em;
}
.vv-assessment-section {
  /* =====================================================
      LARGE RECOMMENDED OPTION
  ===================================================== */
}
.vv-assessment-section .vv-recommended-option {
  margin-top: 6px;
  color: var(--navy);
  font-size: 70px;
  line-height: 0.95;
  font-weight: 600;
  letter-spacing: -0.05em;
}
.vv-assessment-section {
  /* =====================================================
      RECOMMENDED OPTION TEXT
  ===================================================== */
}
.vv-assessment-section .vv-recommended-text {
  max-width: 360px;
  margin-top: 8px;
  color: var(--navy);
  font-size: 19px;
  line-height: 1.35;
  font-weight: 700;
}
.vv-assessment-section {
  /* =====================================================
      ANSWER TITLE
  ===================================================== */
}
.vv-assessment-section .vv-answer-title {
  margin-top: 8px;
  color: var(--blue);
  font-size: 22px;
  font-weight: 700;
  letter-spacing: 0.02em;
}
.vv-assessment-section {
  /* =====================================================
      INFO BOXES
  ===================================================== */
}
.vv-assessment-section .vv-info-box,
.vv-assessment-section .vv-takeaway-box {
  width: 100%;
  box-sizing: border-box;
  text-align: left;
  border-radius: var(--radius);
  padding: 15px 17px;
}
.vv-assessment-section .vv-info-box {
  margin-top: 20px;
  background: color-mix(in srgb, var(--blue) 8%, var(--cream));
  border: 1px solid color-mix(in srgb, var(--blue) 18%, transparent);
}
.vv-assessment-section .vv-takeaway-box {
  margin-top: 10px;
  background: color-mix(in srgb, var(--blue) 12%, var(--cream));
  border: 1px solid color-mix(in srgb, var(--blue) 20%, transparent);
}
.vv-assessment-section {
  /* =====================================================
      INFO HEADINGS
  ===================================================== */
}
.vv-assessment-section .vv-info-heading,
.vv-assessment-section .vv-takeaway-heading {
  margin-bottom: 6px;
  color: var(--blue);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.1em;
}
.vv-assessment-section {
  /* =====================================================
      INFO CONTENT
  ===================================================== */
}
.vv-assessment-section .vv-info-content,
.vv-assessment-section .vv-takeaway-content {
  color: var(--gray);
  font-size: 13px;
  line-height: 1.5;
}
.vv-assessment-section .vv-info-content p,
.vv-assessment-section .vv-takeaway-content p {
  margin: 0;
}
.vv-assessment-section {
  /* =====================================================
      BACK ACTION
  ===================================================== */
}
.vv-assessment-section .vv-back-action {
  color: var(--gray);
  border-top: 1px solid color-mix(in srgb, var(--navy) 10%, transparent);
  padding-top: 14px;
}
.vv-assessment-section {
  /* =====================================================
      KEYBOARD ACCESSIBILITY
  ===================================================== */
}
.vv-assessment-section .vv-flip-toggle:focus-visible + .vv-flip-card {
  outline: 3px solid var(--blue);
  outline-offset: 4px;
}

.vv-assessment-footer {
  display: flex;
  justify-content: center;
  margin-top: 48px;
  padding-bottom: 16px;
}

.vv-view-faq-btn {
  display: inline-flex;
  align-items: center;
