.stories-section {
  --st-heading-size: 36px;
  --st-subheading-size: 16px;
  --st-card-title: 22px;
  --st-card-body: 15px;
  --st-badge-size: 12px;
  --st-section-padding: 72px;
  --st-side-padding: 32px;
  --st-header-gap: 44px;
  --st-container-width: 1240px;
  --st-card-width: 350px;
  --st-card-height: 460px;
  --st-image-height: 210px;
  --st-stage-height: 510px;
  --st-card-padding: 24px;
  --st-near-offset: 320px;
  --st-far-offset: 540px;
  --st-near-depth: -150px;
  --st-far-depth: -300px;
  --st-near-rotation: 25deg;
  --st-far-rotation: 45deg;
  --st-perspective: 1200px;
  --st-nav-size: 48px;
  --st-nav-offset: 0px;
  --st-icon-size: 50px;
  --st-button-gap: 32px;
  --st-content-gap: 12px;
  position: relative;
  width: 100%;
  min-width: 0;
  background-color: #03152e;
  background-image: radial-gradient(circle at 20% 20%, rgba(0, 122, 255, 0.15) 0%, transparent 40%), radial-gradient(circle at 80% 80%, rgba(147, 51, 234, 0.15) 0%, transparent 40%);
  padding: var(--st-section-padding) var(--st-side-padding);
  text-align: center;
  font-family: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  overflow: hidden;
  box-sizing: border-box;
}
.stories-section *,
.stories-section *::before,
.stories-section *::after {
  box-sizing: border-box;
}
.stories-section__header {
  width: 100%;
  max-width: 1000px;
  margin: 0 auto var(--st-header-gap);
}
.stories-section__header .header-badge {
  width: var(--st-icon-size);
  height: var(--st-icon-size);
  margin: 0 auto 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(0, 122, 255, 0.1);
  border: 1px solid rgba(0, 122, 255, 0.3);
  border-radius: 999px;
  backdrop-filter: blur(8px);
}
.stories-section__header .header-badge img,
.stories-section__header .header-badge svg {
  display: block;
  width: 48%;
  height: 48%;
}
.stories-section__header h2 {
  margin: 0 0 10px;
  padding: 0;
  font-family: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: var(--st-heading-size);
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: -0.5px;
  color: #ffffff;
  overflow-wrap: anywhere;
}
.stories-section__header p {
  max-width: 850px;
  margin: 0 auto;
  font-family: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: var(--st-subheading-size);
  line-height: 1.5;
  color: #64748b;
  overflow-wrap: anywhere;
}
.stories-section .carousel-container {
  position: relative;
  width: 100%;
  max-width: var(--st-container-width);
  min-width: 0;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: center;
}
.stories-section .carousel-stage {
  position: relative;
  width: 100%;
  min-width: 0;
  height: var(--st-stage-height);
  perspective: var(--st-perspective);
}
.stories-section .carousel-track {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  transform-style: preserve-3d;
}
.stories-section .story-card {
  position: absolute;
  left: 50%;
  top: 50%;
  width: var(--st-card-width);
  height: var(--st-card-height);
  max-width: 100%;
  margin-left: calc(var(--st-card-width) / -2);
  margin-top: calc(var(--st-card-height) / -2);
  display: flex;
  flex-direction: column;
  min-width: 0;
  background: rgba(15, 23, 42, 0.75);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 20px;
  overflow: hidden;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.37);
  transition: transform 0.6s cubic-bezier(0.25, 1, 0.5, 1), opacity 0.6s cubic-bezier(0.25, 1, 0.5, 1), border-color 0.3s ease;
  backface-visibility: hidden;
}
.stories-section .story-card__image-wrap {
  position: relative;
  width: 100%;
  height: var(--st-image-height);
  flex-shrink: 0;
  overflow: hidden;
}
.stories-section .story-card__image-wrap img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
  opacity: 0.9;
  transition: transform 0.6s cubic-bezier(0.25, 1, 0.5, 1);
}
.stories-section .story-card__image-wrap::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 30%, rgba(15, 23, 42, 0.95) 100%);
  pointer-events: none;
}
.stories-section .story-card__badge {
  position: absolute;
  bottom: 14px;
  left: 14px;
  z-index: 2;
  max-width: calc(100% - 28px);
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 14px;
  background: rgba(15, 23, 42, 0.85);
  backdrop-filter: blur(10px);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 999px;
  color: #007aff;
  font-size: var(--st-badge-size);
  font-weight: 700;
  line-height: 1.35;
  letter-spacing: 0.5px;
  white-space: normal;
  overflow-wrap: anywhere;
}
.stories-section .story-card__badge .badge-icon {
  width: 14px;
  height: 14px;
  flex-shrink: 0;
  color: #f59a18;
}
.stories-section .story-card__content {
  display: flex;
  flex-direction: column;
  flex: 1 1 auto;
  width: 100%;
  min-width: 0;
  min-height: 0;
  padding: var(--st-card-padding);
  text-align: left;
  background-color: #ffffff;
  overflow-y: auto;
  overflow-x: hidden;
  scrollbar-width: thin;
}
.stories-section .story-card__content h3 {
  margin: 0 0 var(--st-content-gap);
  padding: 0;
  font-family: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: var(--st-card-title);
  font-weight: 600;
  line-height: 1.25;
  color: #08274b;
  white-space: normal;
  overflow-wrap: anywhere;
}
.stories-section .story-card__content p {
  margin: 0 0 18px;
  font-family: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: var(--st-card-body);
  font-weight: 400;
  line-height: 1.5;
  color: #475569;
  white-space: normal;
  overflow-wrap: anywhere;
}
.stories-section .story-card__link {
  display: inline-flex;
  align-items: center;
  align-self: flex-start;
  flex-shrink: 0;
  gap: 8px;
  max-width: 100%;
  min-height: 32px;
  margin-top: auto;
  color: #007aff;
  font-family: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-weight: 600;
  font-size: var(--st-card-body);
  line-height: 1.4;
  text-decoration: none;
  overflow-wrap: anywhere;
  transition: color 0.3s ease;
}
.stories-section .story-card__link img,
.stories-section .story-card__link svg {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
  transition: transform 0.3s ease;
}
.stories-section .story-card__link:hover {
  color: #062b66;
}
.stories-section .story-card__link:hover img,
.stories-section .story-card__link:hover svg {
  transform: translateX(5px);
}
.stories-section .story-card__link:focus-visible {
  outline: 2px solid #007aff;
  outline-offset: 3px;
}
.stories-section .story-card.active {
  transform: translate3d(0, 0, 0) rotateY(0deg);
  z-index: 3;
  opacity: 1;
  border-color: rgba(0, 122, 255, 0.4);
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.6), 0 0 20px rgba(0, 122, 255, 0.15);
}
.stories-section .story-card.prev-card {
  transform: translate3d(calc(var(--st-near-offset) * -1), 0, var(--st-near-depth)) rotateY(var(--st-near-rotation));
  z-index: 2;
  opacity: 0.65;
}
.stories-section .story-card.next-card {
  transform: translate3d(var(--st-near-offset), 0, var(--st-near-depth)) rotateY(calc(var(--st-near-rotation) * -1));
  z-index: 2;
  opacity: 0.65;
}
.stories-section .story-card.far-prev {
  transform: translate3d(calc(var(--st-far-offset) * -1), 0, var(--st-far-depth)) rotateY(var(--st-far-rotation));
  z-index: 1;
  opacity: 0.25;
}
.stories-section .story-card.far-next {
  transform: translate3d(var(--st-far-offset), 0, var(--st-far-depth)) rotateY(calc(var(--st-far-rotation) * -1));
  z-index: 1;
  opacity: 0.25;
}
.stories-section .carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  z-index: 10;
  width: var(--st-nav-size);
  height: var(--st-nav-size);
  padding: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 999px;
  background: rgba(22, 27, 34, 0.7);
  backdrop-filter: blur(12px);
  border: 1px solid rgba(255, 255, 255, 0.12);
  color: #ffffff;
  cursor: pointer;
  transition: background 0.3s ease, border-color 0.3s ease;
}
