.stories-section .carousel-btn svg {
  display: block;
  width: 42%;
  height: 42%;
  color: #ffffff;
}
.stories-section .carousel-btn:hover {
  background: rgba(0, 122, 255, 0.2);
  border-color: #007aff;
}
.stories-section .carousel-btn:focus-visible {
  outline: 2px solid #007aff;
  outline-offset: 3px;
}
.stories-section .carousel-btn.prev {
  left: var(--st-nav-offset);
}
.stories-section .carousel-btn.next {
  right: var(--st-nav-offset);
}
.stories-section .btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  max-width: 100%;
  min-height: 44px;
  margin-top: var(--st-button-gap);
  padding: 14px 32px;
  background: linear-gradient(135deg, #062b66 0%, rgb(1.2418300654%, 8.8997821351%, 21.1111111111%) 100%);
  color: #ffffff;
  border-radius: 999px;
  font-family: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: var(--st-card-body);
  font-weight: 600;
  line-height: 1.4;
  text-decoration: none;
  white-space: normal;
  overflow-wrap: anywhere;
  box-shadow: 0 4px 15px rgba(6, 43, 102, 0.3);
  transition: transform 0.3s ease, box-shadow 0.3s ease;
}
.stories-section .btn-primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(6, 43, 102, 0.5);
}
.stories-section .btn-primary:focus-visible {
  outline: 2px solid #ffffff;
  outline-offset: 3px;
}
