.founder-section {
  position: relative;
  width: 100%;
  overflow: hidden;
  background: #fdfbf7;
  padding: 65px 0;
}
.founder-section *,
.founder-section *::before,
.founder-section *::after {
  box-sizing: border-box;
}

.founder-container {
  width: min(1400px, 100% - 64px);
  margin: 0 auto;
}

.founder-hero {
  display: grid;
  grid-template-columns: minmax(0, 1.35fr) minmax(400px, 0.95fr) minmax(220px, 0.48fr);
  gap: 24px;
  align-items: end;
}

.founder-content {
  position: relative;
  z-index: 2;
  padding-bottom: 15px;
}

.founder-eyebrow {
  display: inline-block;
  margin-bottom: 14px;
  font-size: 14px;
  line-height: 1;
  font-weight: 700;
  letter-spacing: 2.5px;
  text-transform: uppercase;
  color: #f59a18;
}
.founder-eyebrow::after {
  content: "";
  display: block;
  width: 42px;
  height: 2px;
  margin-top: 12px;
  background: #f59a18;
}

.founder-name {
  margin: 0;
  font-family: "Arial Narrow", "Roboto Condensed", "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: clamp(42px, 4vw, 72px);
  line-height: 0.95;
  font-weight: 700;
  letter-spacing: -2px;
  color: #08274b;
}

.founder-role {
  margin: 20px 0 0;
  font-size: 14px;
  line-height: 1.2;
  font-weight: 600;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: #64748b;
}

.founder-accent {
  width: 65px;
  height: 4px;
  margin: 22px 0 25px;
  background: #f59a18;
}

.founder-bio {
  max-width: 650px;
}
.founder-bio p {
  margin: 0 0 14px;
  font-size: 16px;
  line-height: 1.7;
  color: #475569;
}
.founder-bio p:last-child {
  margin-bottom: 0;
}

.founder-portrait {
  position: relative;
  min-height: 570px;
  overflow: hidden;
  z-index: 1;
  background: #f59a18;
  border-radius: 280px 0 0 0;
}

.founder-portrait-bg {
  position: absolute;
  inset: 0;
  background: #f59a18;
  z-index: 0;
}

.founder-portrait img {
  position: absolute;
  bottom: 0;
  left: 50%;
  width: 100%;
  height: 100%;
  transform: translateX(-50%);
  object-fit: cover;
  object-position: center top;
  z-index: 2;
}

.founder-dots {
  position: absolute;
  top: 10px;
  right: -25px;
  width: 95px;
  height: 95px;
  background-image: radial-gradient(#f59a18 1.5px, transparent 1.5px);
  background-size: 15px 15px;
  z-index: 3;
  opacity: 0.8;
}

.founder-quote {
  position: relative;
  align-self: start;
  margin-top: 40px;
  min-height: 265px;
  padding: 55px 28px 35px;
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 18px;
  box-shadow: 0 15px 45px rgba(3, 34, 78, 0.06);
  overflow: hidden;
}
.founder-quote p {
  position: relative;
  margin: 0;
  font-size: 18px;
  line-height: 1.55;
  font-weight: 600;
  color: #08274b;
  z-index: 2;
}

.quote-open,
.quote-close {
  position: absolute;
  font-family: Georgia, serif;
  font-size: 75px;
  line-height: 0.7;
  font-weight: 700;
  color: #f59a18;
}

.quote-open {
  top: 25px;
  left: 25px;
}

.quote-close {
  right: 22px;
  bottom: 10px;
}

.quote-line {
  display: block;
  width: 100%;
  height: 1px;
  margin-top: 35px;
  background: #f59a18;
}

.founder-snapshot {
  display: grid;
  grid-template-columns: 1.05fr 0.9fr 0.85fr 1.15fr 0.9fr;
  grid-template-rows: 145px 145px;
  gap: 8px;
  margin-top: 24px;
  border-radius: 18px;
  overflow: hidden;
  background: #ffffff;
  border: 1px solid #e2e8f0;
}

.snapshot-experience {
  grid-column: 1;
  grid-row: 1/3;
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 35px;
  background: #08274b;
  color: #ffffff;
  overflow: hidden;
}

.snapshot-number {
  display: block;
  font-family: "Arial Narrow", "Roboto Condensed", "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: clamp(72px, 5vw, 100px);
  line-height: 0.8;
  font-weight: 300;
  color: #ffffff;
}
.snapshot-number span {
  color: #f59a18;
}

.snapshot-label {
  display: flex;
  flex-direction: column;
  margin-top: 25px;
  gap: 2px;
}
.snapshot-label strong {
  font-size: 14px;
  letter-spacing: 1.5px;
  color: #f59a18;
}
.snapshot-label span {
  font-size: 12px;
  line-height: 1.4;
  letter-spacing: 0.5px;
  color: rgba(255, 255, 255, 0.75);
}

.snapshot-icon {
  position: absolute;
  right: 25px;
  bottom: 20px;
  width: 55px;
  height: 55px;
}
.snapshot-icon svg {
  width: 100%;
  height: 100%;
  fill: none;
  stroke: #f59a18;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.snapshot-card {
  display: flex;
  align-items: center;
  gap: 18px;
  padding: 25px;
  overflow: hidden;
}

.snapshot-card-icon {
  flex: 0 0 55px;
  width: 55px;
  height: 55px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #f59a18;
  border-radius: 12px;
}
.snapshot-card-icon svg {
  width: 32px;
  height: 32px;
  fill: none;
  stroke: #ffffff;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.snapshot-knowledge {
  grid-column: 2;
  grid-row: 1;
  background: #ffffff;
  border-right: 1px solid #e2e8f0;
}
.snapshot-knowledge .snapshot-card-content {
  display: flex;
  flex-direction: column;
}
.snapshot-knowledge span {
  font-size: 12px;
  line-height: 1.35;
  color: #64748b;
}
.snapshot-knowledge strong {
  font-size: 16px;
  line-height: 1.25;
  color: #08274b;
}

.snapshot-city {
  grid-column: 2;
  grid-row: 2;
}

.snapshot-expertise {
  grid-column: 3/5;
  grid-row: 1;
  background: #08274b;
  color: #ffffff;
}
.snapshot-expertise .snapshot-card-icon {
  background: transparent;
  border: 1px solid rgba(255, 255, 255, 0.3);
}
.snapshot-expertise span {
  display: block;
  font-size: 12px;
  line-height: 1.4;
  color: rgba(255, 255, 255, 0.7);
}
.snapshot-expertise strong {
  display: block;
  font-size: 16px;
  line-height: 1.3;
  color: #ffffff;
}

.snapshot-business {
  grid-column: 3;
  grid-row: 2;
}

.snapshot-policy {
  grid-column: 4;
  grid-row: 2;
  background: rgba(245, 154, 24, 0.12);
}
.snapshot-policy .snapshot-card-icon {
  background: #f59a18;
}
.snapshot-policy span {
  display: block;
  font-size: 12px;
  line-height: 1.4;
  color: #64748b;
}
.snapshot-policy strong {
  display: block;
  font-size: 16px;
  line-height: 1.3;
  color: #08274b;
}

.snapshot-document {
  grid-column: 5;
  grid-row: 1/3;
}

.snapshot-image {
  position: relative;
  overflow: hidden;
  background: #e2e8f0;
}
.snapshot-image img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
  filter: grayscale(100%);
  transition: filter 0.3s ease, transform 0.3s ease;
}
.snapshot-image:hover img {
  filter: grayscale(0%);
  transform: scale(1.04);
}

.founder-credentials {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  margin-top: 25px;
  border: 1px solid #e2e8f0;
  background: #ffffff;
  border-radius: 16px;
  overflow: hidden;
}

.credential-item {
  display: flex;
  align-items: center;
  gap: 16px;
  min-height: 105px;
  padding: 18px 22px;
  border-right: 1px solid #e2e8f0;
}
.credential-item:last-child {
  border-right: 0;
}
.credential-item strong {
  display: block;
  margin-bottom: 3px;
  font-size: 22px;
  line-height: 1;
  color: #08274b;
}
.credential-item span {
  display: block;
  font-size: 12px;
  line-height: 1.45;
  text-transform: uppercase;
  color: #64748b;
}

.credential-icon {
  flex: 0 0 46px;
  width: 46px;
  height: 46px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: rgba(245, 154, 24, 0.08);
}
.credential-icon svg {
  width: 27px;
  height: 27px;
  fill: none;
  stroke: #f59a18;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.founder-closing {
  position: relative;
  display: flex;
  align-items: center;
  gap: 22px;
  margin-top: 25px;
  padding: 22px 30px;
  background: #08274b;
  border-radius: 16px;
  overflow: hidden;
}
.founder-closing p {
  position: relative;
  max-width: 900px;
  margin: 0;
  font-size: 16px;
  line-height: 1.55;
  color: #ffffff;
  z-index: 2;
}

.closing-icon {
  flex: 0 0 48px;
  width: 48px;
  height: 48px;
}
.closing-icon svg {
  width: 100%;
  height: 100%;
  fill: none;
  stroke: #f59a18;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.closing-dots {
  position: absolute;
  right: 25px;
  bottom: 15px;
  width: 90px;
  height: 60px;
  background-image: radial-gradient(#f59a18 1.5px, transparent 1.5px);
  background-size: 13px 13px;
  opacity: 0.65;
}

@media (max-width: 1200px) {
  .founder-container {
    width: min(1200px, 100% - 24px);
  }
  .founder-hero {
    grid-template-columns: minmax(0, 1fr) minmax(360px, 0.85fr);
    gap: 30px;
  }
  .founder-quote {
    grid-column: 2;
    grid-row: 1;
    align-self: end;
