  }
  .snapshot-business {
    grid-column: 3;
    grid-row: 2;
  }
  .snapshot-policy {
    grid-column: 2;
    grid-row: 3;
  }
  .snapshot-document {
    grid-column: 3;
    grid-row: 3;
  }
  .founder-credentials {
    grid-template-columns: repeat(2, 1fr);
  }
  .credential-item {
    border-bottom: 1px solid #e2e8f0;
  }
  .credential-item:nth-child(2) {
    border-right: 0;
  }
  .credential-item:nth-child(3), .credential-item:nth-child(4) {
