  }
  .founder-snapshot {
    grid-template-columns: 1fr 1fr;
    grid-template-rows: 160px 160px 160px 160px;
  }
  .snapshot-experience {
    grid-column: 1;
    grid-row: 1/3;
  }
  .snapshot-knowledge {
    grid-column: 2;
    grid-row: 1;
  }
  .snapshot-city {
    grid-column: 2;
    grid-row: 2;
  }
  .snapshot-expertise {
    grid-column: 1;
    grid-row: 3;
  }
  .snapshot-business {
    grid-column: 2;
    grid-row: 3;
  }
  .snapshot-policy {
    grid-column: 1;
    grid-row: 4;
  }
  .snapshot-document {
    grid-column: 2;
    grid-row: 4;
  }
  .founder-credentials {
    grid-template-columns: 1fr 1fr;
  }
