@media (max-width: 600px) {
  .founder-container {
    width: calc(100% - 30px);
  }
  .founder-name {
    font-size: 38px;
    letter-spacing: -1px;
  }
  .founder-role {
    font-size: 11px;
    letter-spacing: 1.5px;
  }
  .founder-bio p {
