  }
  .snapshot-experience {
    min-height: 230px;
    padding: 30px;
  }
  .snapshot-card {
    min-height: 150px;
    border-bottom: 1px solid #e2e8f0;
  }
  .snapshot-image {
    min-height: 180px;
  }
  .founder-credentials {
    display: flex;
    flex-direction: column;
  }
  .credential-item {
    min-height: 90px;
