.mission-media .video-thumbnail-wrapper .video-poster {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transition: transform 0.5s ease;
}
.mission-media .video-thumbnail-wrapper .video-overlay {
  position: absolute;
  inset: 0;
  background: rgba(3, 21, 46, 0.15);
  transition: background 0.3s ease;
}
.mission-media .video-thumbnail-wrapper:hover .video-poster {
  transform: scale(1.03);
}
.mission-media .video-thumbnail-wrapper:hover .video-overlay {
  background: rgba(3, 21, 46, 0.05);
}
.mission-media .video-thumbnail-wrapper:hover .play-btn {
  transform: translate(-50%, -50%) scale(1.1);
}
.mission-media {
