  width: 70px;
  height: 70px;
  padding: 0;
  transition: transform 0.2s ease;
  z-index: 2;
}
.mission-media .play-btn .play-circle-svg {
  width: 100%;
  height: 100%;
}
.mission-media .play-btn .play-circle-svg .svg-bg-circle {
  fill: none;
  stroke: #ffffff;
  stroke-width: 2;
  stroke-opacity: 0.4;
