.mission-content .mission-description {
  font-size: 16px;
  line-height: 1.5;
  color: #475569;
  margin-bottom: 7px;
  font-weight: 500;
}
.mission-content .mission-description-sub {
  font-size: 16px;
  line-height: 1.5;
