.video-modal {
  position: fixed;
  inset: 0;
  z-index: 9999;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.3s ease, visibility 0.3s ease;
}
.video-modal.is-active {
  opacity: 1;
  visibility: visible;
}
.video-modal .video-modal-overlay {
  position: absolute;
  inset: 0;
  background-color: rgba(3, 21, 46, 0.85);
  backdrop-filter: blur(4px);
}
.video-modal .video-modal-content {
  position: relative;
  width: 90%;
  max-width: 900px;
