.insurance-story-hero {
  /* =====================================================
     SLIDE
  ===================================================== */
}
.insurance-story-hero__slide {
  position: absolute;
  inset: 0;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: opacity 0.65s ease, visibility 0.65s ease;
}
.insurance-story-hero__slide.is-active {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
  z-index: 2;
}
.insurance-story-hero {
