}

.flipping-page-leaf {
  position: absolute;
  top: 0;
  bottom: 0;
  right: 0;
  width: 50%;
  transform-origin: left center;
  transform-style: preserve-3d;
  pointer-events: none;
  z-index: 25;
  visibility: hidden;
}
.flipping-page-leaf .leaf-face {
  position: absolute;
  inset: 0;
  background: #fdfbf7;
  padding: 42px;
  backface-visibility: hidden;
  border: 1px solid #e2e8f0;
}
.flipping-page-leaf .leaf-face .leaf-shadow {
  position: absolute;
  inset: 0;
  pointer-events: none;
  transition: opacity 0.85s ease;
}
.flipping-page-leaf .leaf-front {
  transform: rotateY(0deg);
}
.flipping-page-leaf .leaf-front .leaf-shadow {
  background: linear-gradient(to right, rgba(0, 0, 0, 0.45), transparent 45%);
  opacity: 0;
}
.flipping-page-leaf .leaf-back {
  transform: rotateY(180deg);
}
.flipping-page-leaf .leaf-back .leaf-shadow {
  background: linear-gradient(to left, rgba(0, 0, 0, 0.45), transparent 45%);
  opacity: 1;
}
.flipping-page-leaf.is-turning-forward {
  visibility: visible;
  animation: animFlipForward 0.85s cubic-bezier(0.645, 0.045, 0.355, 1) forwards;
}
.flipping-page-leaf.is-turning-forward .leaf-front .leaf-shadow {
  animation: animShadowForward 0.85s ease forwards;
}
.flipping-page-leaf.is-turning-forward .leaf-back .leaf-shadow {
  animation: animShadowBack 0.85s ease forwards;
}
.flipping-page-leaf.is-turning-backward {
  visibility: visible;
  animation: animFlipBackward 0.85s cubic-bezier(0.645, 0.045, 0.355, 1) forwards;
}
.flipping-page-leaf.is-turning-backward .leaf-front .leaf-shadow {
  animation: animShadowBack 0.85s ease forwards;
}
.flipping-page-leaf.is-turning-backward .leaf-back .leaf-shadow {
  animation: animShadowForward 0.85s ease forwards;
}

@keyframes animFlipForward {
  0% {
    transform: rotateY(0deg);
  }
  100% {
    transform: rotateY(-180deg);
  }
}
@keyframes animFlipBackward {
  0% {
    transform: rotateY(-180deg);
  }
  100% {
    transform: rotateY(0deg);
  }
}
@keyframes animShadowForward {
  0% {
    opacity: 0;
  }
  50% {
    opacity: 0.65;
  }
  100% {
    opacity: 1;
  }
}
@keyframes animShadowBack {
  0% {
    opacity: 1;
  }
  50% {
    opacity: 0.65;
  }
  100% {
    opacity: 0;
  }
}
