/* Book viewport */
.book-viewport-3d {
  width: 100%;
  min-width: 0;
  perspective: 2500px;
}

/* The book grows according to its content */
.realistic-open-book {
  width: 100%;
  min-width: 0;
  min-height: clamp(520px, 58vh, 740px);
  height: auto;
  display: flex;
  align-items: stretch;
  overflow: hidden;
}

/* Both pages always have equal height */
.realistic-open-book > .book-page {
  flex: 0 0 50%;
  width: 50%;
  min-width: 0;
  height: auto;
  padding: clamp(20px, 2.8vw, 42px);
}

.page-content-box {
  width: 100%;
  min-width: 0;
  height: 100%;
  min-height: 0;
}

.page-left .story-intro-page,
.page-right .story-content-page {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

/* Responsive title */
.page-left .story-title {
  font-size: clamp(23px, 2.5vw, 42px);
  line-height: 1.16;
  max-width: 100%;
  overflow-wrap: anywhere;
}

/* Responsive image */
.page-left .story-intro-image {
  width: 100%;
  min-width: 0;
  margin-top: auto;
  padding: clamp(6px, 0.8vw, 10px);
}

.page-left .story-intro-image img {
  width: 100%;
  height: clamp(180px, 25vw, 330px);
  max-height: 38vh;
  object-fit: contain;
  object-position: center;
}

/* Story text */
.page-right .story-content-page {
  padding-top: 4px;
}

.page-right .story-paragraphs {
  flex: 1 0 auto;
  min-width: 0;
  padding: 20px 0 12px;
  margin: 0;
  font-size: clamp(13px, 1vw, 16px);
  line-height: 1.7;
  overflow-wrap: anywhere;
}

.page-right .story-paragraphs p {
  margin-bottom: 14px;
}

.page-right .takeaway-banner {
  flex-shrink: 0;
  margin-top: auto;
}

/* Flipping page uses same padding */
.flipping-page-leaf .leaf-face {
  padding: clamp(20px, 2.8vw, 42px);
}

/* Navigation follows actual book height */
.reader-control-row {
  position: relative;
  width: 100%;
  min-height: 45px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: clamp(10px, 2vw, 25px);
  margin: 22px auto 0;
}

.reader-control-row .book-nav-btn {
