}
.vv-pricing-factors {
  /* HEADER — LEFT ALIGNED */
}
.vv-pricing-factors__header {
  max-width: 100%;
  margin: 0 0 26px;
  text-align: left;
}
.vv-pricing-factors__eyebrow {
  display: inline-block;
  margin-bottom: 7px;
