  flex: 0 0 auto;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 27px;
  height: 27px;
  border-radius: 999px;
  background: #eff6ff;
  color: #007aff;
  font-size: 12px;
  font-weight: 700;
}
