  content: "";
  position: absolute;
  left: 14px;
  right: 14px;
  bottom: -1px;
  height: 3px;
  border-radius: 999px 999px 0 0;
  background: #007aff;
}
.vv-pricing-factors {
  /* MAIN PANEL */
}
