.property-transition {
  position: relative;
  width: 100%;
  padding: 60px 26px 48px;
  background: #eff6ff;
  color: #08274b;
  overflow: hidden;
}
.property-transition::before {
  content: "";
  position: absolute;
  width: 420px;
  height: 420px;
  top: -260px;
  right: -180px;
  border-radius: 50%;
  background: rgba(0, 122, 255, 0.05);
  pointer-events: none;
}
.property-transition::after {
  content: "";
  position: absolute;
  width: 360px;
  height: 360px;
  bottom: -260px;
  left: -180px;
  border-radius: 50%;
  background: rgba(0, 122, 255, 0.035);
  pointer-events: none;
}
.property-transition__container {
  position: relative;
  z-index: 1;
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
}
.property-transition__eyebrow {
  margin-bottom: 24px;
  font-family: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 12px;
  font-weight: 700;
  line-height: 1;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: #007aff;
}
.property-transition__content {
  width: 100%;
  max-width: 760px;
  margin: 0 auto;
}
.property-transition__title {
  margin: 0;
  font-family: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: clamp(38px, 5vw, 44px);
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: -0.025em;
  color: #08274b;
}
.property-transition__description {
  max-width: 680px;
  margin: 24px auto 0;
  font-family: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 18px;
  font-weight: 400;
  line-height: 1.5;
  color: #475569;
}
.property-transition__heading-large {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  margin: 32px 0 0;
  font-family: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: clamp(28px, 4vw, 36px);
  font-weight: 700;
  line-height: 1.1;
  color: #007aff;
  text-decoration: none;
  transition: color 0.2s ease, transform 0.2s ease;
}
.property-transition__heading-large span {
  display: inline-block;
  transition: transform 0.2s ease;
}
.property-transition__heading-large:hover {
  color: #062b66;
  transform: translateY(-2px);
}
.property-transition__heading-large:hover span {
  transform: translateX(4px);
}
.property-transition__heading-large:focus-visible {
  outline: 2px solid #007aff;
  outline-offset: 4px;
  border-radius: 8px;
}
.property-transition__journey {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  margin-top: 56px;
  flex-wrap: wrap;
  gap: 8px 0;
}
.property-transition__step {
  min-height: 32px;
  padding: 7px 13px;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  border: 1px solid #e2e8f0;
  border-radius: 999px;
  background: #ffffff;
  color: #64748b;
  font-family: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 12px;
  line-height: 1;
  text-decoration: none;
  white-space: nowrap;
  transition: background 0.2s ease, border-color 0.2s ease, color 0.2s ease;
}
.property-transition__step:hover {
  border-color: #007aff;
  color: #007aff;
}
.property-transition__step--active {
  background: #eff6ff;
  border-color: rgba(0, 122, 255, 0.25);
  color: #062b66;
  cursor: default;
}
.property-transition__step-number {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.04em;
  opacity: 0.75;
}
.property-transition__step-label {
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.01em;
}
.property-transition__line {
  width: 20px;
  height: 1px;
  margin: 0 4px;
  background: #e2e8f0;
}
@media (max-width: 768px) {
  .property-transition {
    padding: 80px 26px 40px;
  }
  .property-transition__title {
    font-size: 38px;
  }
  .property-transition__description {
    font-size: 16px;
  }
  .property-transition__journey {
    margin-top: 48px;
  }
