.paacthero {
  font-family: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  position: relative;
  width: 100%;
  min-height: 100vh;
  height: auto;
  overflow: visible;
  background: #fdfbf7;
}
.paacthero .paacthero-slider-container {
  position: relative;
  width: 100%;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}
.paacthero .paacthero-slide {
  position: relative;
  width: 100%;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: opacity 0.6s ease, visibility 0.6s ease;
}
.paacthero .paacthero-slide.active {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
}
.paacthero .paacthero-slide.active .paacthero-slide-image-wrapper {
  transform: scale(1);
}
.paacthero .paacthero-slide.active .paacthero-slide-content {
  opacity: 1;
  transform: translateY(0);
}
.paacthero .paacthero-slide-image-wrapper {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  background-position: center right;
  background-size: cover;
  background-repeat: no-repeat;
  transform: scale(1.05);
  transition: transform 6s cubic-bezier(0.25, 1, 0.5, 1);
  z-index: 0;
}
.paacthero .paacthero-slide-image-overlay {
  position: absolute;
  inset: 0;
  z-index: 1;
  background: linear-gradient(90deg, rgba(253, 251, 247, 0.98) 0%, rgba(253, 251, 247, 0.95) 48%, rgba(253, 251, 247, 0.7) 72%, rgba(253, 251, 247, 0.15) 100%);
