  width: 100%;
  /* Removed rigid height limits to allow dynamic sizing */
}
.motor-split-process-section .flip-card .flip-card-inner {
  position: relative;
  width: 100%;
  height: 100%;
  text-align: left;
  transition: transform 0.3s ease;
  transform-style: preserve-3d;
  box-shadow: 0 4px 15px rgba(0, 0, 0, 0.03);
  border-radius: 8px;
}
