  transform: rotateY(180deg);
}
.motor-split-process-section .flip-card .flip-card-front,
.motor-split-process-section .flip-card .flip-card-back {
  position: relative; /* Changed from absolute to allow content height to dictate sizing */
  width: 100%;
  min-height: 150px; /* Ensures consistent minimum baseline height */
  backface-visibility: hidden;
  display: flex;
  align-items: center;
  padding: 16px 18px;
  border-radius: 8px;
  gap: 12px;
  border: 1px solid #e2e8f0;
  box-sizing: border-box;
