  display: flex;
  align-items: center;
  justify-content: center;
  width: 60px;
  flex: 0 0 60px;
  background: linear-gradient(135deg, #ffffff 0%, #eff6ff 100%);
  border-top: 1px solid #e2e8f0;
  border-bottom: 1px solid #e2e8f0;
  border-left: 1px solid #e2e8f0;
  box-shadow: inset -3px 0 6px rgba(8, 39, 75, 0.06);
  z-index: 2;
}
.claim-docs__ribbon-number span {
  color: #007aff;
  font-family: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 26px;
  font-weight: 800;
  line-height: 1;
  letter-spacing: -0.5px;
}
.claim-docs__ribbon-number .claim-docs__fold-shadow {
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  width: 10px;
  background: linear-gradient(to right, rgba(8, 39, 75, 0.02), rgba(8, 39, 75, 0.1));
  pointer-events: none;
}
.claim-docs__ribbon-arrow {
  position: relative;
  flex: 1;
  display: flex;
  align-items: center;
  background-color: #ffffff;
  border-top: 1px solid #e2e8f0;
  border-right: 1px solid #e2e8f0;
  border-bottom: 1px solid #e2e8f0;
  padding: 14px 16px 14px 20px;
  clip-path: polygon(0 0, calc(100% - 12px) 0, 100% 50%, calc(100% - 12px) 100%, 0 100%, 12px 50%);
  margin-left: -1px;
  box-shadow: 0 4px 12px rgba(8, 39, 75, 0.04);
  transition: background-color 0.2s ease, transform 0.2s ease, border-color 0.2s ease;
}
.claim-docs__ribbon-arrow:hover {
  background-color: #f8fafc;
  border-color: #007aff;
  transform: translateY(-2px);
}
.claim-docs__ribbon-content {
  display: flex;
  flex-direction: column;
  gap: 6px;
  width: 100%;
}
.claim-docs__ribbon-content p {
  margin: 0;
  color: #08274b;
  font-size: 13px;
  font-weight: 500;
  line-height: 1.45;
  display: -webkit-box;
  -webkit-line-clamp: 4;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.claim-docs__ribbon-icon {
  display: inline-grid;
  width: 24px;
  height: 24px;
  place-items: center;
  background-color: #eff6ff;
  color: #007aff;
  border-radius: 8px;
  font-size: 13px;
}
.claim-docs__section {
  margin-bottom: 64px;
}
.claim-docs__section-heading {
  margin-bottom: 24px;
}
.claim-docs__section-heading h3 {
  margin: 0 0 7px;
  color: #08274b;
  font-size: clamp(22px, 2.5vw, 22px);
  font-weight: 700;
  line-height: 1.2;
}
.claim-docs__section-heading p {
  margin: 0;
  color: #64748b;
  font-size: 14px;
  line-height: 1.5;
}
.claim-docs__bento-container {
  display: grid;
  grid-template-columns: 1.5fr 1fr;
  gap: 20px;
  align-items: stretch;
}
.claim-docs__bento-left {
  position: relative;
}
.claim-docs__active-panel {
  display: none;
  background-color: #ffffff;
  border: 2px solid #007aff;
  border-radius: 20px;
  padding: 36px;
  color: #08274b;
  box-shadow: 0 20px 40px rgba(0, 122, 255, 0.12);
  height: 100%;
  animation: panelFadeIn 0.2s ease ease both;
}
.claim-docs__active-panel.is-active {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}
.claim-docs__active-panel .claim-docs__panel-symbol {
  background-color: rgba(0, 122, 255, 0.1);
  border: 1px solid #007aff;
  color: #007aff;
}
.claim-docs__active-panel .claim-docs__panel-kicker {
  color: #007aff;
  font-weight: 700;
}
.claim-docs__active-panel .claim-docs__panel-title {
  color: #08274b;
}
.claim-docs__active-panel .claim-docs__panel-desc {
  color: #475569;
}
.claim-docs__active-panel .claim-docs__progress-track {
  background-color: #eff6ff;
}
.claim-docs__active-panel .claim-docs__panel-progress-text {
  color: #64748b;
}
.claim-docs__active-panel .claim-docs__checkbox-label {
  background-color: #f59a18;
  border: 1px solid #e2e8f0;
}
.claim-docs__active-panel .claim-docs__checkbox-label:hover {
  border-color: #007aff;
}
.claim-docs__active-panel .claim-docs__checkbox-label.is-checked {
  background-color: rgba(16, 185, 129, 0.08);
  border-color: #10b981;
}
.claim-docs__active-panel .claim-docs__checkbox-label.is-checked .claim-docs__item-text {
  color: #64748b;
}
.claim-docs__active-panel .claim-docs__custom-check {
  background-color: #ffffff;
  border: 1.5px solid #e2e8f0;
}
.claim-docs__active-panel .claim-docs__item-text {
  color: #08274b;
  font-weight: 600;
}
.claim-docs__active-panel .claim-docs__item-status {
  color: #007aff;
  font-weight: 700;
}
.claim-docs__active-panel .claim-docs__panel-footer {
  border-top: 1px solid #e2e8f0;
}
.claim-docs__active-panel .claim-docs__panel-footer p {
  color: #64748b;
}
.claim-docs__active-panel .claim-docs__footer-icon {
  border: 1px solid #f59a18;
  background-color: rgba(245, 154, 24, 0.1);
  color: #f59a18;
}
.claim-docs__bento-right {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
}
.claim-docs__bento-card {
  position: relative;
  overflow: hidden;
  border: 1.5px solid #e2e8f0;
  border-radius: 16px;
  padding: 20px;
  text-align: left;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  min-height: 140px;
  box-shadow: 0 6px 16px rgba(8, 39, 75, 0.06);
  transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;
  opacity: 0.75;
  filter: saturate(0.85);
}
.claim-docs__bento-card:hover {
  transform: translateY(-3px);
  box-shadow: 0 12px 25px rgba(0, 122, 255, 0.25);
  border-color: #007aff;
  opacity: 1;
  filter: saturate(1);
}
.claim-docs__bento-card.is-active {
  opacity: 1;
  filter: saturate(1);
  border: 5px solid #f59a18;
  box-shadow: 0 16px 35px rgba(245, 154, 24, 0.45), 0 0 0 2px rgba(245, 154, 24, 0.2);
  transform: translateY(-2px);
}
.claim-docs__bento-card.is-active .claim-docs__bento-overlay {
  background: linear-gradient(to top, rgba(3, 21, 46, 0.75) 0%, rgba(3, 21, 46, 0.2) 100%);
}
.claim-docs__bento-card.is-active .claim-docs__bento-title {
  color: #ffffff;
  font-size: 16px;
  text-shadow: 0 2px 8px rgba(0, 0, 0, 0.7);
}
.claim-docs__bento-card.is-active .claim-docs__bento-badge {
  background-color: #007aff;
  color: #ffffff;
  box-shadow: 0 4px 12px rgba(0, 122, 255, 0.6);
  font-size: 11px;
  letter-spacing: 0.8px;
}
.claim-docs__bento-card.is-active .claim-docs__bento-num {
  color: #f59a18;
  font-size: 20px;
  font-weight: 900;
  text-shadow: 0 2px 8px rgba(0, 0, 0, 0.8);
}
.claim-docs__bento-card--od {
  grid-column: span 2;
}
.claim-docs__bento-card--theft {
  grid-column: span 1;
}
.claim-docs__bento-card--tp_injury {
  grid-column: span 1;
}
.claim-docs__bento-card--tp_death {
  grid-column: span 2;
}
.claim-docs__bento-card--calamity {
  grid-column: span 2;
}
.claim-docs__bento-bg {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-size: cover;
  background-position: center;
  z-index: 1;
  transition: transform 0.5s ease;
}
.claim-docs__bento-card:hover .claim-docs__bento-bg {
  transform: scale(1.05);
}
.claim-docs__bento-overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: linear-gradient(to top, rgba(3, 21, 46, 0.92) 0%, rgba(3, 21, 46, 0.35) 100%);
  z-index: 2;
  transition: background 0.2s ease;
}
.claim-docs__bento-card-top {
  position: relative;
  z-index: 3;
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.claim-docs__bento-icon {
  font-size: 22px;
  background: rgba(255, 255, 255, 0.2);
  padding: 6px;
  border-radius: 8px;
  backdrop-filter: blur(4px);
}
.claim-docs__bento-badge {
  position: relative;
  z-index: 3;
  padding: 4px 10px;
  background-color: rgba(255, 255, 255, 0.9);
  backdrop-filter: blur(4px);
  border-radius: 999px;
  color: #08274b;
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}
.claim-docs__bento-card-content {
  position: relative;
  z-index: 3;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-top: 12px;
}
.claim-docs__bento-title {
  margin: 0;
  color: #ffffff;
  font-size: 15px;
  font-weight: 700;
  line-height: 1.3;
  text-shadow: 0 2px 4px rgba(3, 21, 46, 0.3);
}
.claim-docs__bento-num {
  color: #eff6ff;
  font-size: 16px;
  font-weight: 800;
  text-shadow: 0 2px 4px rgba(3, 21, 46, 0.3);
}
.claim-docs__notice {
  display: flex;
  align-items: flex-start;
  gap: 24px;
  padding: 26px;
  background-color: #fdfbf7;
  border: 1px solid #e2e8f0;
  border-radius: 20px;
  margin-top: 64px;
}
.claim-docs__notice-icon {
  display: grid;
  width: 32px;
  height: 32px;
  flex: 0 0 32px;
  place-items: center;
  background-color: rgba(245, 154, 24, 0.15);
  border: 1px solid #f59a18;
  border-radius: 999px;
  color: #f59a18;
  font-size: 16px;
  font-weight: 700;
}
.claim-docs__notice-content {
  min-width: 0;
}
.claim-docs__notice-content h3 {
  margin: 0 0 7px;
  color: #08274b;
  font-size: 18px;
  font-weight: 700;
}
.claim-docs__notice-content p {
  margin: 0 0 7px;
  color: #475569;
  font-size: 14px;
  line-height: 1.75;
}
.claim-docs__notice-content p:last-child {
  margin-bottom: 0;
}
.claim-docs__notice-content strong {
  color: #08274b;
}
@media (max-width: 1199px) {
  .claim-docs__ribbon-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (max-width: 991px) {
  .claim-docs__bento-container {
    grid-template-columns: minmax(0, 1fr);
  }
}
@media (max-width: 600px) {
  .claim-docs__ribbon-grid {
    grid-template-columns: minmax(0, 1fr);
    gap: 12px;
  }
  .claim-docs__active-panel {
    padding: 22px;
  }
  .claim-docs__bento-right {
    grid-template-columns: minmax(0, 1fr);
  }
  .claim-docs__bento-card--od, .claim-docs__bento-card--tp_death, .claim-docs__bento-card--calamity {
    grid-column: span 1;
  }
}

@keyframes panelFadeIn {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
.motor-network-section .flip-card-back {
  justify-content: center;
  gap: 12px;
}

.key-takeaway-box {
  display: flex;
  gap: 16px;
  background-color: #ffffff;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-left: 4px solid #f59a18;
  border-radius: 20px;
  padding: 20px 24px;
  margin-top: 40px;
  align-items: flex-start;
}
.key-takeaway-box .takeaway-icon {
  font-size: 1.8rem;
  line-height: 1;
  flex-shrink: 0;
}
.key-takeaway-box .takeaway-content {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.key-takeaway-box .takeaway-content .takeaway-title {
  font-size: 1.05rem;
  font-weight: 700;
