.insurance-checklist-wrapper {
  width: 100%;
  max-width: 100%;
  margin: 0 auto;
  padding: clamp(24px, 4vw, 64px) clamp(16px, 4vw, 48px);
  font-family: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  box-sizing: border-box;
}
.insurance-checklist-wrapper *, .insurance-checklist-wrapper *::before, .insurance-checklist-wrapper *::after {
  box-sizing: border-box;
}
.insurance-checklist-wrapper .checklist-header {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 32px;
  padding: 36px 40px;
  background-color: #ffffff;
  border-radius: 16px;
}
.insurance-checklist-wrapper .checklist-header .header-content {
  flex: 1 1 auto;
  min-width: 0;
}
.insurance-checklist-wrapper .checklist-header h2 {
  margin: 0;
  color: #08274b;
  font-size: 44px;
  font-weight: 600;
  line-height: 1.2;
}
.insurance-checklist-wrapper .checklist-header .section-subtitle {
  max-width: 850px;
  margin: 10px 0 0;
  color: black;
  font-size: 16px;
  line-height: 1.5;
}
.insurance-checklist-wrapper .checklist-header .total-progress-badge {
  flex: 0 0 auto;
  min-width: 105px;
  padding: 18px 20px;
  background-color: #f8fafc;
  border: 1px solid #e2e8f0;
  border-radius: 8px;
  color: #08274b;
  font-size: 18px;
  font-weight: 700;
  text-align: center;
}
.insurance-checklist-wrapper .checklist-header .total-progress-badge .badge-label {
  display: block;
  margin-top: 4px;
  color: #64748b;
  font-size: 11px;
  font-weight: 400;
}
.insurance-checklist-wrapper .checklist-grid-container {
  max-width: 1100px;
  align-items: center;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 20px;
  margin-top: 24px;
  background: transparent;
  border: none;
  padding: 0;
}
.insurance-checklist-wrapper .checklist-card {
  background-color: #eff6ff;
  border: 1px solid #e2e8f0;
  border-radius: 16px;
  transition: all 0.2s ease;
  grid-column: span 1;
}
.insurance-checklist-wrapper .checklist-card:hover {
  border-color: rgba(0, 122, 255, 0.4);
  box-shadow: 0 4px 12px rgba(3, 21, 46, 0.04);
}
.insurance-checklist-wrapper .checklist-card .card-toggle-btn {
  width: 100%;
  padding: 16px 18px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: none;
  border: none;
  cursor: pointer;
  text-align: left;
  font-family: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}
.insurance-checklist-wrapper .checklist-card .card-toggle-btn .card-icon-title {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
}
.insurance-checklist-wrapper .checklist-card .card-toggle-btn .card-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  background-color: #eff6ff;
  color: #007aff;
  border-radius: 8px;
  flex: 0 0 auto;
}
.insurance-checklist-wrapper .checklist-card .card-toggle-btn .card-titles {
  min-width: 0;
}
.insurance-checklist-wrapper .checklist-card .card-toggle-btn .card-titles .card-title {
  margin: 0;
  color: #08274b;
  font-size: 20px;
  font-weight: 600;
  line-height: 1.3;
}
.insurance-checklist-wrapper .checklist-card .card-toggle-btn .card-titles .title-collapsed {
  display: block;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 220px;
}
.insurance-checklist-wrapper .checklist-card .card-toggle-btn .card-titles .title-expanded {
  display: none;
}
.insurance-checklist-wrapper .checklist-card .card-toggle-btn .card-titles .card-subtitle-text {
  display: block;
  margin-top: 2px;
  color: black;
  font-size: 14px;
}
.insurance-checklist-wrapper .checklist-card .card-toggle-btn .card-meta-right {
  display: flex;
  align-items: center;
  gap: 10px;
  flex: 0 0 auto;
}
.insurance-checklist-wrapper .checklist-card .card-toggle-btn .card-meta-right .card-progress-indicator {
  font-size: 11px;
  color: #64748b;
  font-weight: 500;
}
.insurance-checklist-wrapper .checklist-card .card-toggle-btn .card-meta-right .accordion-arrow {
  display: flex;
  align-items: center;
  color: #64748b;
  transition: transform 0.2s ease;
}
.insurance-checklist-wrapper .checklist-card .card-dropdown-body {
  display: none;
  padding: 0 18px 18px 18px;
  border-top: 1px solid #e2e8f0;
}
.insurance-checklist-wrapper .checklist-card .card-dropdown-body .folder-intro {
  margin: 12px 0;
  color: black;
  font-size: 16px;
  line-height: 1.5;
}
.insurance-checklist-wrapper .checklist-card .card-dropdown-body .checklist-items-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
  list-style: none;
  margin: 0;
  padding: 0;
}
.insurance-checklist-wrapper .checklist-card .card-dropdown-body .checklist-item-row {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 10px 12px;
  background-color: white;
  border: 1px solid #e2e8f0;
  border-radius: 8px;
  transition: background-color 0.15s ease;
}
.insurance-checklist-wrapper .checklist-card .card-dropdown-body .checklist-item-row .binder-checkbox {
  appearance: none;
  position: relative;
  flex: 0 0 auto;
  width: 16px;
  height: 16px;
  margin: 2px 0 0;
  background-color: #ffffff;
  border: 2px solid #64748b;
  border-radius: 4px;
  cursor: pointer;
}
.insurance-checklist-wrapper .checklist-card .card-dropdown-body .checklist-item-row .binder-checkbox:checked {
  background-color: #10b981;
  border-color: #10b981;
}
.insurance-checklist-wrapper .checklist-card .card-dropdown-body .checklist-item-row .binder-checkbox:checked::after {
  content: "";
  position: absolute;
  left: 3px;
  top: 0px;
  width: 5px;
  height: 9px;
  border: solid #ffffff;
  border-width: 0 2px 2px 0;
  transform: rotate(45deg);
}
.insurance-checklist-wrapper .checklist-card .card-dropdown-body .checklist-item-row label {
  flex: 1;
  min-width: 0;
  margin: 0;
  color: #08274b;
  font-size: 16px;
  line-height: 1.5;
  cursor: pointer;
}
.insurance-checklist-wrapper .checklist-card .card-dropdown-body .checklist-item-row .binder-checkbox:checked + label {
  color: #64748b;
  text-decoration: line-through;
}
.insurance-checklist-wrapper .checklist-card.active {
  border-color: #007aff;
  box-shadow: 0 6px 20px rgba(0, 122, 255, 0.1);
  grid-column: span 3;
}
.insurance-checklist-wrapper .checklist-card.active .card-toggle-btn {
  background-color: rgba(0, 122, 255, 0.02);
  border-radius: 16px 16px 0 0;
}
.insurance-checklist-wrapper .checklist-card.active .card-toggle-btn .card-titles .title-collapsed {
  display: none;
}
.insurance-checklist-wrapper .checklist-card.active .card-toggle-btn .card-titles .title-expanded {
  display: block;
}
.insurance-checklist-wrapper .checklist-card.active .card-toggle-btn .accordion-arrow {
  transform: rotate(180deg);
  color: #007aff;
}
.insurance-checklist-wrapper .checklist-card.active .card-dropdown-body {
  display: block;
}
@media (max-width: 1200px) {
  .insurance-checklist-wrapper .checklist-grid-container {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .insurance-checklist-wrapper .checklist-card.active {
    grid-column: span 2;
  }
}
@media (max-width: 768px) {
  .insurance-checklist-wrapper {
    padding: 16px 8px;
  }
  .insurance-checklist-wrapper .checklist-header {
    flex-direction: column;
    align-items: flex-start;
    padding: 24px;
    gap: 16px;
  }
  .insurance-checklist-wrapper .checklist-header h2 {
    font-size: 24px;
  }
  .insurance-checklist-wrapper .checklist-header .total-progress-badge {
    align-self: stretch;
  }
  .insurance-checklist-wrapper .checklist-grid-container {
    grid-template-columns: 1fr;
  }
  .insurance-checklist-wrapper .checklist-card.active {
    grid-column: span 1;
  }
}

.travelinsurancehero {
  font-family: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  position: relative;
  width: 100%;
  height: 100vh;
  min-height: 650px;
  overflow: hidden;
  background: #fdfbf7;
}
.travelinsurancehero .travelinsurancehero-slider-container {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
}
.travelinsurancehero .travelinsurancehero-slide {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: opacity 0.8s ease, visibility 0.8s ease;
}
.travelinsurancehero .travelinsurancehero-slide.active {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
