/* Timeline Layout */
.timeline {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 26px;
  max-width: 1100px;
}
.timeline__line {
  position: absolute;
  top: 20px;
  bottom: 20px;
  left: 17px;
  width: 2px;
  background-color: rgb(70%, 84.3529411765%, 100%);
  z-index: 1;
}
.timeline__item {
  position: relative;
  display: flex;
  align-items: flex-start;
  gap: 26px;
  z-index: 2;
  /* Active State styling */
}
.timeline__item.is-active .timeline__badge {
  background-color: #007aff;
  color: #ffffff;
  box-shadow: 0 0 0 4px rgb(76%, 87.4823529412%, 100%);
}
.timeline__item.is-active .timeline__card {
  border-color: rgb(50%, 73.9215686275%, 100%);
  box-shadow: 0 4px 20px rgba(8, 39, 75, 0.06);
}
.timeline__item.is-active .accordion-icon::after {
  transform: rotate(90deg);
  opacity: 0;
}
.timeline__item {
  /* Next Suggested Step Indicator */
}
.timeline__item.next-suggested .timeline__badge {
  animation: pulse-ring 2s infinite;
  background-color: #f59a18;
}
.timeline__item.next-suggested .timeline__card {
  border-color: rgba(245, 154, 24, 0.5);
}
.timeline__badge {
  width: 36px;
  height: 36px;
  border-radius: 999px;
  background-color: #03152e;
  color: #ffffff;
  font-size: 12px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  transition: 0.2s ease;
}
.timeline__card {
  flex: 1;
  background-color: #f8fafc;
  border: 1px solid #e2e8f0;
  border-radius: 16px;
  padding: 0;
  overflow: hidden;
  transition: 0.2s ease;
}
.timeline {
  /* Interactive Button Header */
}
.timeline__trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px;
  background: transparent;
  border: none;
  cursor: pointer;
  text-align: left;
}
.timeline__trigger:hover .card-title {
  color: #007aff;
}
.timeline {
  /* Accordion Content Smooth Slide Transition */
}
.timeline__content {
  overflow: hidden;
  transition: max-height 0.5s ease;
}
.timeline__content-inner {
  padding: 0 16px 16px 16px;
}

.card-title {
  font-size: 18px;
  font-weight: 700;
  color: #08274b;
  margin: 0;
  transition: color 0.2s ease;
}

/* Plus/Minus Accordion Toggle Icon */
.accordion-icon {
  position: relative;
  width: 16px;
  height: 16px;
  flex-shrink: 0;
}
.accordion-icon::before, .accordion-icon::after {
  content: "";
  position: absolute;
  background-color: #08274b;
  border-radius: 2px;
  transition: transform 0.2s ease, opacity 0.2s ease;
}
.accordion-icon::before {
  top: 7px;
  left: 0;
  width: 16px;
  height: 2px;
}
.accordion-icon::after {
  top: 0;
  left: 7px;
  width: 2px;
  height: 16px;
}

.card-text {
  font-size: 16px;
  color: #475569;
  line-height: 1.5;
  margin-top: 0;
}
.card-text:not(:last-child) {
