  background: #ffffff;
  color: #08274b;
  overflow: hidden;
}
.property-transition::before {
  content: "";
  position: absolute;
  width: 420px;
  height: 420px;
  top: -260px;
  right: -180px;
  border-radius: 50%;
  background: rgba(0, 122, 255, 0.035);
  pointer-events: none;
}
.property-transition::after {
  content: "";
  position: absolute;
  width: 360px;
  height: 360px;
  bottom: -260px;
  left: -180px;
  border-radius: 50%;
  background: rgba(0, 122, 255, 0.025);
  pointer-events: none;
}
