}
.policy-callout-box .callout-content strong {
  color: #08274b;
  font-size: 16px;
  font-weight: 700;
  display: block;
  margin-bottom: 6px;
}
.policy-callout-box .callout-content p {
  font-size: 14px;
  color: #475569;
  line-height: 1.5;
  margin: 0;
}

/* Keyframe for next-step subtle pulsing ring */
@keyframes pulse-ring {
  0% {
    box-shadow: 0 0 0 0 rgba(245, 154, 24, 0.6);
  }
  70% {
    box-shadow: 0 0 0 10px rgba(245, 154, 24, 0);
  }
  100% {
    box-shadow: 0 0 0 0 rgba(245, 154, 24, 0);
  }
}
